"""Create a reviewable synthesis after all training, replay and metrics finish."""
from pathlib import Path
import sys,time,json,hashlib
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/modeling/four_expert_combinations/v1'
def md(d):
    return '\n'.join(['| '+' | '.join(d.columns)+' |','| '+' | '.join(['---']*len(d.columns))+' |']+['| '+' | '.join(str(v) for v in r)+' |' for r in d.itertuples(index=False,name=None)])
def main():
    while not (OUT/'finalizer_complete.json').exists():time.sleep(30)
    metrics=pd.read_csv(OUT/'tables/metrics.csv');presentation=pd.read_csv(OUT/'tables/presentation_RMSE_R2.csv');tests=pd.read_csv(OUT/'tables/paired_tests.csv');regions=pd.read_csv(OUT/'tables/regions.csv');weights=pd.read_csv(OUT/'tables/weights_by_fold.csv');protocols=['random','climate_profile','municipality','spatial'];names=['CT3','L40','Compact14','Reference26','B1','B2','B3','B4','B5','B6'];presentation=presentation.set_index('experiment').loc[names].reset_index();ref=metrics[metrics.experiment=='Reference26'].set_index('protocol');dominant=[];joint=[];rows=[]
    for n in names[4:]:
        z=metrics[metrics.experiment==n].set_index('protocol');delta=z.loc[protocols].rmse-ref.loc[protocols].rmse;allbetter=bool((delta < -1e-12).all());dominant.extend([n] if allbetter else []);ct=metrics[metrics.experiment=='CT3'].set_index('protocol');jointgoal=all(z.loc[p,'rmse']<=ref.loc[p,'rmse']+1e-12 and z.loc[p,'within_05']>=ct.loc[p,'within_05']-1e-12 and z.loc[p,'p95_absolute']<=ref.loc[p,'p95_absolute']+1e-12 for p in ['random','spatial']);joint.extend([n] if jointgoal else [])
        rows.append(dict(experiment=n,delta_random=f'{delta["random"]:+.4f}',delta_profile=f'{delta["climate_profile"]:+.4f}',delta_municipal=f'{delta["municipality"]:+.4f}',delta_spatial=f'{delta["spatial"]:+.4f}',delta_fresh=f'{z.loc["fresh_97_41","rmse"]-ref.loc["fresh_97_41","rmse"]:+.4f}'))
    ranking=pd.DataFrame(rows);ranking.to_csv(OUT/'tables/deltas_vs_reference26.csv',index=False)
    decision=('Hay candidatas con menor RMSE puntual en los cuatro protocolos originales: '+', '.join(dominant)+'. Esto no demuestra superioridad ni autoriza promoción automática.') if dominant else 'Ninguna de las seis combinaciones reduce el RMSE en los cuatro protocolos originales frente a Reference26. Se conserva Reference26 como referencia; no se declara un nuevo Champion.'
    goal=('Cumplen descriptivamente el objetivo conjunto en aleatoria y espacial: '+', '.join(joint)+'.') if joint else 'Ninguna combinación conserva simultáneamente el RMSE y percentil95 de Reference26 y la proporción dentro de±.5 de C-T3 en aleatoria y espacial. No se ha resuelto por completo ese compromiso.'
    selected=tests[(tests.reference=='Reference26')&(tests.p_holm<.05)];significance='Ningún contraste de las mezclas frente a Reference26 supera Holm.' if selected.empty else 'Contrastes frente a Reference26 que superan Holm: '+', '.join(f'{r.experiment}/{r.protocol} (deltaRMSE={r.delta_rmse:+.4f},pHolm={r.p_holm:.4g})' for r in selected.itertuples())+'. El signo de delta define mejora o deterioro.'
    spatial=metrics[metrics.protocol=='spatial'].set_index('experiment').loc[names].reset_index()[['experiment','mae','bias','p95_absolute','within_05']]
    for c in spatial.columns[1:]:spatial[c]=spatial[c].map(lambda v:f'{v:.4f}')
    regional=regions[(regions.protocol=='spatial')&(regions.kind=='Municipio')&regions.zone.isin(['Almoloya','Chignahuapan','Singuilucan','Calpulalpan','Cuautepec de Hinojosa'])].copy();regional['RMSE_bias']=[f'{r.rmse:.4f} / {r.bias:+.4f}' for r in regional.itertuples()];regional=regional.pivot(index='experiment',columns='zone',values='RMSE_bias').reindex(names).reset_index()
    descriptions=['B1: C-T3 + peso constante del desplazamiento Reference26−C-T3.','B2: C-T3 + peso constante del desplazamiento Compact14−C-T3.','B3: mezcla convexa constante Reference26/L40.','B4: mezcla convexa regularizada C-T3/Reference26/L40.','B5: mezcla C-T3/Reference26 con cuatro indicadores de desacuerdo y soporte.','B6: mezcla Reference26/L40 con desacuerdo, soporte y dispersión de etiquetas vecinas del entrenamiento.']
    text='# Seis combinaciones: síntesis de evidencia\n\n'+decision+'\n\n'+goal+'\n\n'+significance+'\n\n## Modelos\n\n'+'\n'.join('- '+s for s in descriptions)+'\n\n## Mismos65 folds: RMSE t/ha / R²\n\n'+md(presentation[['experiment']+protocols])+'\n\n## Banco nuevo97/41 separado\n\n'+md(presentation[['experiment','fresh_97_41']])+'\n\nSon16 particiones nuevas de las mismas138 respuestas ya investigadas; no validación independiente. Cada métrica se calcula en41 casos por partición y luego se promedia. No mezclar con las OOF completas de los65 folds ni con el banco histórico de GeoC.\n\n## Diferencias de RMSE frente a Reference26\n\nNegativo favorece la combinación.\n\n'+md(ranking)+'\n\n## Distribución espacial de errores\n\n'+md(spatial)+'\n\nError=predicho−observado; positivo sobreestima. Menor sesgo no implica menor dispersión. El umbral±.5 y el percentil95 responden preguntas diferentes del RMSE.\n\n## Municipios espaciales: RMSE / sesgo\n\n'+md(regional)+'\n\nAlmoloya tiene10 parcelas, Cuautepec5, Singuilucan16, Calpulalpan30 y Chignahuapan71. Estas cifras describen resultados y no se convierten en reglas municipales. Omitir regiones del cómputo no reajusta modelos; ver omissions.csv.\n\n## Alcance y complejidad\n\nB1/B5 reutilizan C-T3 que ya forma parte de Reference26 y conservan sus26 entradas. B2 conserva las14 entradas de Compact14. B3/B4/B6 requieren además la representación C4 completa de L40;20 componentes PCA no equivalen a20 mediciones originales. Los pesos condicionales no son importancias causales.\n\nLos pesos se aprenden exclusivamente de predicciones internas de expertos reajustados sin la consulta: incluso la intensidad R3 se selecciona dentro de ese entrenamiento. Las penalizaciones meta se congelaron y no se seleccionó la mejor variante sobre folds externos. Se conserva el cambio de tamaño entrenamiento-crossfit frente a reajuste final. L40 conserva PCA transductiva sobre197X, sin etiquetas ocultas; esto no prueba generalización inductiva a parcelas nuevas.\n\nLas comparaciones son exploratorias tras amplia reutilización de las mismas etiquetas. Se realizan130 contrastes con Holm. En espacial hay5 bloques y el test exacto bilateral tiene p mínima .0625: no obtener significación no demuestra igualdad. Las tablas de selección retrospectiva de expertos usan el rendimiento observado, no son modelos aplicables ni límites inferiores de una mezcla convexa.\n\n## Entrega y decisión\n\nLos resultados no autorizan cambios automáticos del Champion. Una ventaja pequeña o localizada debe valorarse junto con complejidad, pérdida por región, cuartiles e intraperfil. Antes de recomendar otra capa se debe comprobar su ganancia frente a la mezcla constante y su estabilidad territorial. Si no hay mejora consistente, priorizar cierre, interpretación y demostración del modelo existente sobre nuevas búsquedas.\n\nSe conservan los138 rendimientos, modelos anteriores y59PRED. No se entrenó modelo final138 ni se generaron predicciones59. Scripts503–513, OOF, modelos, pesos, pruebas, Excel y auditorías están en la estructura del repositorio.\n'
    target=ROOT/'documentation/four_expert_combinations_conclusions.md';target.write_text(text,encoding='utf-8');audit=json.loads((OUT/'delivery_audit.json').read_text());audit['artifact_sha256'][str(target)]=hashlib.sha256(target.read_bytes()).hexdigest();audit['interpretation_complete']=True;(OUT/'delivery_audit.json').write_text(json.dumps(audit,indent=2));print(decision);print(goal);print(significance);print(presentation.to_string(index=False),flush=True)
if __name__=='__main__':main()
